# Find 8-regions
from collections import deque

def find_regions(grid):
    regions = []
    visited = set()
    rows = len(grid)

    def bfs(start_r, start_c, target_val):
        region = []
        queue = deque([(start_r, start_c)])
        visited.add((start_r, start_c))

        while queue:
            r, c = queue.popleft()
            if 0 <= r < rows and 0 <= c < len(grid[r]):
                if grid[r][c] == target_val:
                    region.append((r, c))
                    # Add all 4-connected neighbors
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < len(grid[nr]):
                            if grid[nr][nc] == target_val and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                queue.append((nr, nc))
        return region

    for r in range(rows):
        for c in range(len(grid[r])):
            if grid[r][c] == 8 and (r, c) not in visited:
                region = bfs(r, c, 8)
                print(f"  Region starting at ({r},{c}): {len(region)} cells")
                r_min, r_max = min(x[0] for x in region), max(x[0] for x in region)
                c_min, c_max = min(x[1] for x in region), max(x[1] for x in region)
                print(f"    BB: rows {r_min}-{r_max}, cols {c_min}-{c_max}")
                regions.append(region)
    return regions

print("\nAnalyzing 8-regions:")
regions = find_regions(rows)

